using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Web.Script.Serialization;
using System.Xml.Linq;
using Microsoft.Win32;
namespace Aurora {
public static class RegistryValueCodec {
    public static XElement Encode(object value,RegistryValueKind kind){if(kind==RegistryValueKind.Unknown)throw new InvalidDataException("Unknown registry kind cannot be backed up");return new XElement("encoded",Convert.ToBase64String(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(value))));}
    public static object Decode(XElement encoded,RegistryValueKind kind){string json=Encoding.UTF8.GetString(Convert.FromBase64String(encoded.Value));var parser=new JavaScriptSerializer();switch(kind){case RegistryValueKind.DWord:return parser.Deserialize<int>(json);case RegistryValueKind.QWord:return parser.Deserialize<long>(json);case RegistryValueKind.None:case RegistryValueKind.Binary:return parser.Deserialize<byte[]>(json);case RegistryValueKind.MultiString:return parser.Deserialize<string[]>(json);case RegistryValueKind.String:case RegistryValueKind.ExpandString:return parser.Deserialize<string>(json);default:throw new InvalidDataException("Unsupported registry kind");}}
    public static bool Equal(object a,object b){if(a is byte[]&&b is byte[])return ((byte[])a).SequenceEqual((byte[])b);if(a is string[]&&b is string[])return ((string[])a).SequenceEqual((string[])b);return Object.Equals(a,b);}
}
public interface IRegistryTreeStore {XElement CaptureTree(string hive,string path);void DeleteTree(string hive,string path);void RestoreTree(string hive,string path,XElement tree);bool TreeExists(string hive,string path);}
public sealed partial class WindowsRegistryStore:IRegistryTreeStore {
    public bool TreeExists(string hive,string path){using(var key=Root(hive).OpenSubKey(path))return key!=null;}
    public XElement CaptureTree(string hive,string path){using(var key=Root(hive).OpenSubKey(path)){int count=0;return key==null?new XElement("absent"):Capture(key,ref count);}}
    static XElement Capture(RegistryKey key,ref int count){if(++count>3000)throw new IOException("Registry subtree exceeds backup limit");var node=new XElement("key");foreach(string name in key.GetValueNames()){var kind=key.GetValueKind(name);node.Add(new XElement("value",new XAttribute("name",name),new XAttribute("kind",kind),RegistryValueCodec.Encode(key.GetValue(name,null,RegistryValueOptions.DoNotExpandEnvironmentNames),kind)));}foreach(string name in key.GetSubKeyNames())using(var sub=key.OpenSubKey(name)){var child=Capture(sub,ref count);child.Add(new XAttribute("name",name));node.Add(child);}return node;}
    public void DeleteTree(string hive,string path){if(!TweakRegistryEngine.TreeAllowed(hive,path))throw new InvalidDataException("Registry tree is outside tweak scope");Root(hive).DeleteSubKeyTree(path,false);}
    public void RestoreTree(string hive,string path,XElement tree){if(!TweakRegistryEngine.TreeAllowed(hive,path))throw new InvalidDataException("Registry tree is outside tweak scope");if(tree.Name=="absent")return;using(var key=Root(hive).CreateSubKey(path))Restore(key,tree);}
    static void Restore(RegistryKey key,XElement node){foreach(var value in node.Elements("value")){var kind=(RegistryValueKind)Enum.Parse(typeof(RegistryValueKind),(string)value.Attribute("kind"));key.SetValue((string)value.Attribute("name"),RegistryValueCodec.Decode(value.Element("encoded"),kind),kind);}foreach(var child in node.Elements("key")){string name=(string)child.Attribute("name");if(String.IsNullOrEmpty(name)||name.Contains("\\")||name=="..")throw new InvalidDataException("Invalid registry subtree name");using(var sub=key.CreateSubKey(name))Restore(sub,child);}}
}
public sealed partial class MemoryRegistryStore:IRegistryTreeStore {
    public bool TreeExists(string h,string p){return values.Keys.Any(x=>x.StartsWith(h+"\\"+p+"\\",StringComparison.OrdinalIgnoreCase));}
    public XElement CaptureTree(string h,string p){var node=new XElement("memory-tree");foreach(var pair in values.Where(x=>x.Key.StartsWith(h+"\\"+p+"\\",StringComparison.OrdinalIgnoreCase)))node.Add(new XElement("entry",new XAttribute("key",pair.Key),new XAttribute("kind",pair.Value.Kind),RegistryValueCodec.Encode(pair.Value.Value,pair.Value.Kind)));return node;}
    public void DeleteTree(string h,string p){foreach(string key in values.Keys.Where(x=>x.StartsWith(h+"\\"+p+"\\",StringComparison.OrdinalIgnoreCase)).ToArray())values.Remove(key);}
    public void RestoreTree(string h,string p,XElement tree){foreach(var item in tree.Elements("entry")){var kind=(RegistryValueKind)Enum.Parse(typeof(RegistryValueKind),(string)item.Attribute("kind"));values[(string)item.Attribute("key")]=new RegistrySnapshot{Exists=true,Kind=kind,Value=RegistryValueCodec.Decode(item.Element("encoded"),kind)};}}
}
public sealed partial class Journal {
    public void RegistryDelete(string title,string hive,string path,string name){lock(this){var before=store.Read(hive,path,name);if(!before.Exists)return;var record=new XElement("change",new XAttribute("title",title),new XAttribute("hive",hive),new XAttribute("path",path),new XAttribute("name",name),new XAttribute("existed",true),new XAttribute("kind",before.Kind),new XAttribute("state","prepared"),RegistryValueCodec.Encode(before.Value,before.Kind));string file=Path.Combine(Folder,DateTime.UtcNow.ToString("yyyyMMddHHmmssfffffff")+"-"+Guid.NewGuid().ToString("N")+".xml");AtomicFiles.SaveXml(record,file);store.Delete(hive,path,name);if(store.Read(hive,path,name).Exists)throw new IOException("Registry value was not deleted");record.SetAttributeValue("state","applied");AtomicFiles.SaveXml(record,file);Log(title,"Deleted value / backup: "+Path.GetFileName(file));}}
    public void RegistryTreeDelete(string title,string hive,string path){lock(this){if(!TweakRegistryEngine.TreeAllowed(hive,path))throw new InvalidDataException("Registry tree is outside tweak scope");var trees=store as IRegistryTreeStore;if(trees==null)throw new InvalidOperationException("Registry provider cannot back up subtrees");if(!trees.TreeExists(hive,path))return;var record=new XElement("tree-change",new XAttribute("title",title),new XAttribute("hive",hive),new XAttribute("path",path),new XAttribute("state","prepared"),trees.CaptureTree(hive,path));string file=Path.Combine(Folder,DateTime.UtcNow.ToString("yyyyMMddHHmmssfffffff")+"-"+Guid.NewGuid().ToString("N")+".xml");AtomicFiles.SaveXml(record,file);trees.DeleteTree(hive,path);if(trees.TreeExists(hive,path))throw new IOException("Registry subtree was not deleted");record.SetAttributeValue("state","applied");AtomicFiles.SaveXml(record,file);Log(title,"Deleted subtree / backup: "+Path.GetFileName(file));}}
    void RestoreTree(XElement record){var trees=store as IRegistryTreeStore;if(trees==null)throw new InvalidOperationException("Registry provider cannot restore subtrees");string hive=(string)record.Attribute("hive"),path=(string)record.Attribute("path");if(trees.TreeExists(hive,path))throw new IOException(L.T("A chave foi recriada após o ajuste. Revise o backup antes de restaurá-la.","The key was recreated after the tweak. Review the backup before restoring it."));trees.RestoreTree(hive,path,record.Elements().First());}
}
public static class TweakRegistryEngine {
    public static bool TreeAllowed(string hive,string path){if(hive!="HKLM"&&hive!="HKCU"&&hive!="HKCR")return false;string p=(path??"").ToLowerInvariant();return p.Contains(@"\explorer\desktop\namespace\")||p.Contains(@"\explorer\mycomputer\namespace\")||p.Contains(@"\shellex\contextmenuhandlers\")||p.StartsWith(@"software\classes\*\shell\")||p.StartsWith(@"software\classes\directory\shell\");}
    public static string Identity(TweakSetting value){return (value.Hive+"|"+value.Path.TrimEnd('\\')+"|"+(value.DeleteTree?"<TREE>":value.Name)+(value.PolicyPage==null?"":"|page:"+value.PolicyPage)).ToLowerInvariant();}
    public static bool Same(TweakSetting a,TweakSetting b){return a.Delete==b.Delete&&a.DeleteTree==b.DeleteTree&&(a.Delete||a.DeleteTree||a.Kind==b.Kind&&RegistryValueCodec.Equal(a.Value,b.Value));}
    public static string Signature(Tweak tweak){return String.Join("\n",tweak.Settings().Select(x=>Identity(x)+"|"+(x.DeleteTree?"tree":x.Delete?"delete":x.Kind+"|"+RegistryValueCodec.Encode(x.Value,x.Kind).Value)).OrderBy(x=>x,StringComparer.Ordinal));}
    public static bool Conflict(Tweak a,Tweak b){return a.Settings().Any(x=>b.Settings().Any(y=>Identity(x)==Identity(y)&&!Same(x,y)));}
    public static void Apply(Journal journal,Tweak tweak){foreach(var s in tweak.Settings())if(s.Hive=="HKLM"&&s.Path.StartsWith(@"SYSTEM\CurrentControlSet\Services\",StringComparison.OrdinalIgnoreCase)&&s.Name=="Start"&&!new WindowsRegistryStore().Read(s.Hive,s.Path,"Start").Exists)throw new InvalidOperationException(L.T("Serviço ausente nesta instalação; nenhuma chave foi criada.","Service is absent from this installation; no key was created."));foreach(var s in tweak.Settings()){if(s.PolicyPage!=null)journal.RegistryPageChange("Tweak:"+tweak.Id,s);else if(s.DeleteTree)journal.RegistryTreeDelete("Tweak:"+tweak.Id,s.Hive,s.Path);else if(s.Delete)journal.RegistryDelete("Tweak:"+tweak.Id,s.Hive,s.Path,s.Name);else journal.RegistryChange("Tweak:"+tweak.Id,s.Hive,s.Path,s.Name,s.Value,s.Kind);}}
    public static bool? State(Tweak tweak,IRegistryStore store){bool unknown=false;foreach(var s in tweak.Settings()){if(s.DeleteTree){var trees=store as IRegistryTreeStore;if(trees==null){unknown=true;continue;}if(trees.TreeExists(s.Hive,s.Path))return false;}else{var v=store.Read(s.Hive,s.Path,s.Name);if(s.PolicyPage!=null){try{if(SettingsVisibility.Hidden(v.Exists?Convert.ToString(v.Value):"",s.PolicyPage)!=Convert.ToBoolean(s.Value))return false;}catch{return null;}continue;}if(s.Delete){if(v.Exists)return false;}else if(!v.Exists)unknown=true;else if(!RegistryValueCodec.Equal(v.Value,s.Value))return false;}}return unknown?(bool?)null:true;}
}
}
